1	// Package compact converts full.jsonl transcripts into a normalized,
2	// compact transcript.jsonl format. Only shared formatting is contained here.
3	package compact
4	
5	import (
6		"bufio"
7		"bytes"
8		"encoding/json"
9		"fmt"
10		"io"
11		"strings"
12	
13		"github.com/entireio/cli/cmd/entire/cli/textutil"
14		"github.com/entireio/cli/cmd/entire/cli/transcript"
15	)
16	
17	// MetadataFields provides metadata fields written to every output line.
18	type MetadataFields struct {
19		Agent      string // e.g. "claude-code"
20		CLIVersion string // e.g. "0.42.0"
21		StartLine  int    // checkpoint_transcript_start (0 = no truncation)
22	}
23	
24	// transcriptLine is the uniform output format for every line in transcript.jsonl.
25	// Field order is guaranteed by encoding/json (struct declaration order).
26	type transcriptLine struct {
27		V            int             `json:"v"`
28		Agent        string          `json:"agent"`
29		CLIVersion   string          `json:"cli_version"`
30		Type         string          `json:"type"`
31		TS           json.RawMessage `json:"ts,omitempty"`
32		ID           string          `json:"id,omitempty"`
33		InputTokens  int             `json:"input_tokens,omitempty"`
34		OutputTokens int             `json:"output_tokens,omitempty"`
35		Content      json.RawMessage `json:"content"`
36	}
37	
38	// newTranscriptLine returns a transcriptLine pre-filled with the shared
39	// metadata fields that are identical on every output line.
40	func newTranscriptLine(opts MetadataFields) transcriptLine {
41		return transcriptLine{
42			V:          1,
43			Agent:      opts.Agent,
44			CLIVersion: opts.CLIVersion,
45		}
46	}
47	
48	const toolResultStatusError = "error"
49	
50	// toolResultJSON is the compact result object inlined into tool_use blocks.
51	type toolResultJSON struct {
52		Output     string              `json:"output"`
53		Status     string              `json:"status"`
54		File       *toolResultFileJSON `json:"file,omitempty"`
55		MatchCount int                 `json:"matchCount,omitempty"`
56	}
57	
58	// toolResultFileJSON carries structured file metadata from Read/Edit tool results.
59	type toolResultFileJSON struct {
60		FilePath string `json:"filePath"`
61		NumLines int    `json:"numLines,omitempty"`
62	}
63	
64	// userTextBlock is a text block within user message content.
65	type userTextBlock struct {
66		ID   string `json:"id,omitempty"`
67		Text string `json:"text"`
68	}
69	
70	// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
71	//
72	// The output format puts version, agent, and cli_version on every line,
73	// merges streaming assistant fragments with the same message ID, and inlines
74	// tool results into the preceding assistant's tool_use blocks:
75	//
76	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
77	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
78	func Compact(content []byte, opts MetadataFields) ([]byte, error) {
79		// Single-object formats (OpenCode, Gemini) must be detected on the raw
80		// content. SliceFromLine operates on newline offsets which would cut a
81		// JSON object mid-value and break parsing. These compactors handle
82		// StartLine internally as a message-index offset.
83		if isOpenCodeFormat(content) {
84			return compactOpenCode(content, opts)
85		}
86	
87		if isGeminiFormat(content) {
88			return compactGemini(content, opts)
89		}
90	
91		truncated := transcript.SliceFromLine(content, opts.StartLine)
92		if truncated == nil {
93			truncated = []byte{}
94		}
95	
96		return compactJSONL(truncated, opts)
97	}
98	
99	// droppedTypes are JSONL entry types that carry no parser-relevant data.
100	var droppedTypes = map[string]bool{
101		"progress":              true,
102		"file-history-snapshot": true,
103		"queue-operation":       true,
104		"system":                true,
105	}
106	
107	// userAliases maps JSONL type/role values to the canonical "user" kind.
108	// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
109	var userAliases = map[string]bool{
110		transcript.TypeUser: true,
111		"human":             true,
112	}
113	
114	// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
115	// JSONL transcript line. It checks the "type" field, then falls back to "role".
116	// Returns "" for unrecognised or dropped entries.
117	func normalizeKind(raw map[string]json.RawMessage) string {
118		kind := unquote(raw["type"])
119		if kind == "" {
120			kind = unquote(raw["role"])
121		}
122	
123		if droppedTypes[kind] {
124			return ""
125		}
126		if userAliases[kind] {
127			return transcript.TypeUser
128		}
129		if kind == transcript.TypeAssistant {
130			return transcript.TypeAssistant
131		}
132		return ""
133	}
134	
135	// parsedEntry is an intermediate representation of a JSONL line used during
136	// the two-pass compact conversion.
137	type parsedEntry struct {
138		kind         string // "user" or "assistant"
139		ts           json.RawMessage
140		id           string            // message ID (assistant only)
141		userID       string            // prompt ID (user only, e.g. Claude's promptId)
142		inputTokens  int               // API input tokens (assistant only)
143		outputTokens int               // API output tokens (assistant only)
144		content      json.RawMessage   // stripped assistant content array, or nil
145		userText     string            // extracted user text
146		userImages   []json.RawMessage // image blocks from user messages
147		toolResults  []toolResultEntry // user tool_result entries
148	}
149	
150	// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
151	// transcript.jsonl format.
152	func compactJSONL(content []byte, opts MetadataFields) ([]byte, error) {
153		base := newTranscriptLine(opts)
154	
155		// Pass 1: parse all lines into intermediate entries.
156		entries, err := parseJSONLEntries(content)
157		if err != nil {
158			return nil, err
159		}
160	
161		// Pass 2: merge and emit.
162		var result []byte
163		for i := 0; i < len(entries); i++ {
164			e := entries[i]
165	
166			switch e.kind {
167			case transcript.TypeAssistant:
168				// Merge consecutive assistant entries with the same message ID.
169				merged := e
170				for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
171					i++
172					merged = mergeAssistantEntries(merged, entries[i])
173				}
174	
175				// Look ahead for user tool_result entries to inline.
176				if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
177					userEntry := entries[i+1]
178					merged = inlineToolResults(merged, userEntry)
179					i++ // consume the user tool_result entry
180	
181					// If the consumed user entry also had text or image content, emit it
182					// as a separate user line after the assistant.
183					if userEntry.userText != "" || len(userEntry.userImages) > 0 {
184						emitAssistant(&result, base, merged)
185						emitUser(&result, base, userEntry)
186						continue
187					}
188				}
189	
190				if isEmptyContentArray(merged.content) {
191					continue
192				}
193	
194				emitAssistant(&result, base, merged)
195	
196			case transcript.TypeUser:
197				// User entries that are purely tool results were already consumed
198				// by the assistant look-ahead above. If we reach one here it was
199				// not preceded by an assistant with a matching tool_use, so emit
200				// it only if it has text or image content.
201				if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
202					continue
203				}
204				emitUser(&result, base, e)
205			}
206		}
207	
208		return result, nil
209	}
210	
211	func emitAssistant(result *[]byte, base transcriptLine, e parsedEntry) {
212		line := base
213		line.Type = transcript.TypeAssistant
214		line.TS = e.ts
215		line.ID = e.id
216		line.InputTokens = e.inputTokens
217		line.OutputTokens = e.outputTokens
218		line.Content = e.content
219		appendLine(result, line)
220	}
221	
222	func emitUser(result *[]byte, base transcriptLine, e parsedEntry) {
223		var blocks []json.RawMessage
224	
225		// Text block (with optional prompt ID).
226		if e.userText != "" || len(e.userImages) == 0 {
227			b, err := json.Marshal(userTextBlock{ID: e.userID, Text: e.userText})
228			if err != nil {
229				return
230			}
231			blocks = append(blocks, b)
232		}
233	
234		// Image blocks passed through verbatim.
235		blocks = append(blocks, e.userImages...)
236	
237		contentJSON, err := json.Marshal(blocks)
238		if err != nil {
239			return
240		}
241	
242		line := base
243		line.Type = transcript.TypeUser
244		line.TS = e.ts
245		line.Content = contentJSON
246		appendLine(result, line)
247	}
248	
249	// appendLine marshals a transcriptLine and appends it (with newline) to result.
250	func appendLine(result *[]byte, line transcriptLine) {
251		b, err := json.Marshal(line)
252		if err != nil {
253			return
254		}
255		*result = append(*result, b...)
256		*result = append(*result, '\n')
257	}
258	
259	// parseJSONLEntries parses all JSONL lines into intermediate entries,
260	// filtering dropped types and malformed lines.
261	func parseJSONLEntries(content []byte) ([]parsedEntry, error) {
262		reader := bufio.NewReader(bytes.NewReader(content))
263		var entries []parsedEntry
264	
265		for {
266			lineBytes, err := reader.ReadBytes('\n')
267			if err != nil && err != io.EOF {
268				return nil, fmt.Errorf("reading JSONL line: %w", err)
269			}
270	
271			if len(bytes.TrimSpace(lineBytes)) > 0 {
272				if e, ok := parseLine(lineBytes); ok {
273					entries = append(entries, e)
274				}
275			}
276	
277			if err == io.EOF {
278				break
279			}
280		}
281	
282		return entries, nil
283	}
284	
285	// parseLine converts a single JSONL line into a parsedEntry.
286	// Returns ok=false for dropped/malformed lines.
287	func parseLine(lineBytes []byte) (parsedEntry, bool) {
288		var raw map[string]json.RawMessage
289		if err := json.Unmarshal(lineBytes, &raw); err != nil {
290			return parsedEntry{}, false
291		}
292	
293		kind := normalizeKind(raw)
294		if kind == "" {
295			return parsedEntry{}, false
296		}
297	
298		e := parsedEntry{
299			kind: kind,
300			ts:   raw["timestamp"],
301		}
302	
303		msg := parseMessage(raw)
304	
305		switch kind {
306		case transcript.TypeAssistant:
307			if msg != nil {
308				e.id = unquote(msg["id"])
309				if contentRaw, ok := msg["content"]; ok {
310					e.content = stripAssistantContent(contentRaw)
311				}
312				e.inputTokens, e.outputTokens = extractUsageTokens(msg)
313			}
314	
315		case transcript.TypeUser:
316			e.userID = unquote(raw["promptId"])
317			if msg != nil {
318				if contentRaw, ok := msg["content"]; ok {
319					uc := extractUserContent(contentRaw)
320					e.userText = uc.text
321					e.userImages = uc.images
322					e.toolResults = uc.toolResults
323				}
324			}
325			// Enrich tool results with metadata from toolUseResult.
326			if turRaw, ok := raw["toolUseResult"]; ok {
327				var tur map[string]json.RawMessage
328				if json.Unmarshal(turRaw, &tur) == nil {
329					e.toolResults = enrichToolResults(e.toolResults, tur)
330				}
331			}
332		}
333	
334		return e, true
335	}
336	
337	// mergeAssistantEntries combines two assistant entries with the same message ID.
338	// Content arrays are concatenated; the later timestamp and token counts win
339	// (streaming fragments report cumulative usage, so the last fragment is final).
340	func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
341		merged := a
342		merged.ts = b.ts
343		if b.inputTokens > 0 {
344			merged.inputTokens = b.inputTokens
345		}
346		if b.outputTokens > 0 {
347			merged.outputTokens = b.outputTokens
348		}
349	
350		var aBlocks, bBlocks []json.RawMessage
351		_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
352		_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
353		all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
354		if data, err := json.Marshal(all); err == nil {
355			merged.content = data
356		}
357	
358		return merged
359	}
360	
361	// inlineToolResults adds "result" fields to matching tool_use blocks in the
362	// assistant entry's content, using outputs from user tool_result entries.
363	func inlineToolResults(assistant, user parsedEntry) parsedEntry {
364		var blocks []map[string]json.RawMessage
365		if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
366			return assistant
367		}
368	
369		for _, tr := range user.toolResults {
370			// Find the tool_use block matching this tool_use_id.
371			idx := -1
372			for i := len(blocks) - 1; i >= 0; i-- {
373				if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
374					if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
375						idx = i
376						break
377					}
378				}
379			}
380			// No matching tool_use block: do not attach a result to unrelated content.
381			if idx == -1 {
382				continue
383			}
384	
385			blocks[idx]["result"] = buildToolResult(tr)
386		}
387	
388		if data, err := json.Marshal(blocks); err == nil {
389			assistant.content = data
390		}
391	
392		return assistant
393	}
394	
395	// buildToolResult constructs the compact result object for a tool_use block,
396	// including optional rich metadata (file, matchCount) when available.
397	func buildToolResult(tr toolResultEntry) json.RawMessage {
398		r := toolResultJSON{
399			Output:     tr.output,
400			Status:     "success",
401			MatchCount: tr.matchCount,
402		}
403		if tr.isError {
404			r.Status = toolResultStatusError
405		}
406		if tr.file != nil {
407			r.File = &toolResultFileJSON{
408				FilePath: tr.file.filePath,
409				NumLines: tr.file.numLines,
410			}
411		}
412		b, err := json.Marshal(r)
413		if err != nil {
414			return nil
415		}
416		return b
417	}
418	
419	// extractUsageTokens extracts input_tokens and output_tokens from a Claude
420	// message's "usage" object. Returns (0, 0) if usage is absent or malformed.
421	func extractUsageTokens(msg map[string]json.RawMessage) (inputTokens, outputTokens int) {
422		usageRaw, ok := msg["usage"]
423		if !ok {
424			return 0, 0
425		}
426		var usage struct {
427			InputTokens  int `json:"input_tokens"`
428			OutputTokens int `json:"output_tokens"`
429		}
430		if json.Unmarshal(usageRaw, &usage) != nil {
431			return 0, 0
432		}
433		return usage.InputTokens, usage.OutputTokens
434	}
435	
436	// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
437	func isEmptyContentArray(raw json.RawMessage) bool {
438		var arr []json.RawMessage
439		return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
440	}
441	
442	func hasToolResults(e parsedEntry) bool {
443		return len(e.toolResults) > 0
444	}
445	
446	type toolResultEntry struct {
447		toolUseID string
448		output    string
449		isError   bool
450		// Rich metadata extracted from toolUseResult (optional).
451		file       *toolResultFile // Read/Edit: file path and line count
452		matchCount int             // Grep: number of matching files
453	}
454	
455	// toolResultFile carries structured file metadata from Read/Edit tool results.
456	type toolResultFile struct {
457		filePath string
458		numLines int // 0 if not available (e.g. Edit results)
459	}
460	
461	// enrichToolResults extracts structured metadata from a toolUseResult envelope
462	// and attaches it to the corresponding tool result entries.
463	//
464	// Claude Code's toolUseResult has different shapes per tool:
465	//   - Bash:  {stdout, stderr, interrupted, ...}
466	//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
467	//   - Grep:  {numFiles, numLines, filenames, content, mode}
468	//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
469	func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
470		// Bash-style: stdout provides the output text.
471		if stdout := unquote(tur["stdout"]); stdout != "" {
472			switch len(results) {
473			case 0:
474				// Keep compatibility with transcripts that only include toolUseResult.
475				results = append(results, toolResultEntry{output: stdout})
476			case 1:
477				results[0].output = stdout
478			}
479		}
480	
481		// Read-style: file object with filePath and numLines.
482		if fileRaw, ok := tur["file"]; ok {
483			var file struct {
484				FilePath string `json:"filePath"`
485				NumLines int    `json:"numLines"`
486			}
487			if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
488				applyToSingleResult(results, func(tr *toolResultEntry) {
489					tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
490				})
491			}
492		}
493	
494		// Edit-style: top-level filePath.
495		if filePath := unquote(tur["filePath"]); filePath != "" {
496			applyToSingleResult(results, func(tr *toolResultEntry) {
497				// Edit results don't have numLines.
498				tr.file = &toolResultFile{filePath: filePath}
499			})
500		}
501	
502		// Grep-style: numFiles as match count.
503		if numFilesRaw, ok := tur["numFiles"]; ok {
504			var n int
505			if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
506				applyToSingleResult(results, func(tr *toolResultEntry) {
507					tr.matchCount = n
508				})
509			}
510		}
511	
512		return results
513	}
514	
515	// applyToSingleResult applies fn to the first (and expected only) tool result.
516	// toolUseResult is a single-tool envelope, so this is only meaningful when
517	// there's exactly one result entry.
518	func applyToSingleResult(results []toolResultEntry, fn func(*toolResultEntry)) {
519		if len(results) == 1 {
520			fn(&results[0])
521		}
522	}
523	
524	// parseMessage extracts and parses the "message" field from a JSONL transcript
525	// line. All JSONL agents nest content inside a "message" object.
526	func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
527		msgRaw, ok := raw["message"]
528		if !ok {
529			return nil
530		}
531		var msg map[string]json.RawMessage
532		if json.Unmarshal(msgRaw, &msg) == nil {
533			return msg
534		}
535		return nil
536	}
537	
538	// userContent holds the extracted parts of a user message content array.
539	type userContent struct {
540		text        string
541		images      []json.RawMessage
542		toolResults []toolResultEntry
543	}
544	
545	// extractUserContent separates user message content into text, images, and tool_result entries.
546	// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
547	func extractUserContent(contentRaw json.RawMessage) userContent {
548		var str string
549		if json.Unmarshal(contentRaw, &str) == nil {
550			return userContent{text: textutil.StripIDEContextTags(str)}
551		}
552	
553		var blocks []json.RawMessage
554		if json.Unmarshal(contentRaw, &blocks) != nil {
555			return userContent{}
556		}
557	
558		var uc userContent
559	
560		for _, blockRaw := range blocks {
561			var block map[string]json.RawMessage
562			if json.Unmarshal(blockRaw, &block) != nil {
563				continue
564			}
565			blockType := unquote(block["type"])
566	
567			switch blockType {
568			case "tool_result":
569				var isErr bool
570				if raw, ok := block["is_error"]; ok {
571					_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
572				}
573				uc.toolResults = append(uc.toolResults, toolResultEntry{
574					toolUseID: unquote(block["tool_use_id"]),
575					output:    unquote(block["content"]),
576					isError:   isErr,
577				})
578	
579			case "image":
580				uc.images = append(uc.images, blockRaw)
581	
582			case transcript.ContentTypeText:
583				stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
584				if stripped != "" {
585					uc.text += stripped + "\n\n"
586				}
587			}
588		}
589	
590		uc.text = strings.TrimSpace(uc.text)
591		return uc
592	}
593	
594	func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
595		var str string
596		if json.Unmarshal(contentRaw, &str) == nil {
597			return contentRaw
598		}
599	
600		var blocks []map[string]json.RawMessage
601		if json.Unmarshal(contentRaw, &blocks) != nil {
602			return contentRaw
603		}
604	
605		result := make([]map[string]json.RawMessage, 0, len(blocks))
606		for _, block := range blocks {
607			blockType := unquote(block["type"])
608	
609			if blockType == "thinking" || blockType == "redacted_thinking" {
610				continue
611			}
612	
613			if blockType == transcript.ContentTypeToolUse {
614				stripped := make(map[string]json.RawMessage)
615				copyField(stripped, block, "type")
616				copyField(stripped, block, "id")
617				copyField(stripped, block, "name")
618				copyField(stripped, block, "input")
619				result = append(result, stripped)
620				continue
621			}
622	
623			result = append(result, block)
624		}
625	
626		b, err := json.Marshal(result)
627		if err != nil {
628			return contentRaw
629		}
630		return b
631	}
632	
633	// copyField copies a single key from src to dst if it exists.
634	func copyField(dst, src map[string]json.RawMessage, key string) {
635		if v, ok := src[key]; ok {
636			dst[key] = v
637		}
638	}
639	
640	// unquote JSON-decodes a raw message as a string. Returns "" on failure.
641	func unquote(raw json.RawMessage) string {
642		var s string
643		if json.Unmarshal(raw, &s) == nil {
644			return s
645		}
646		return ""
647	}
648

