1	package compact
2	
3	import (
4		"bufio"
5		"bytes"
6		"encoding/json"
7	
8		"github.com/entireio/cli/cmd/entire/cli/transcript"
9	)
10	
11	// isDroidFormat checks whether JSONL content uses Factory AI Droid's envelope
12	// format. It scans lines looking for one with a recognizable "type" field - if
13	// the first such line has type "message" with a nested "message" object, it's
14	// Droid format. Unrecognized types (session_start, session_event) are skipped.
15	func isDroidFormat(content []byte) bool {
16		scanner := bufio.NewScanner(bytes.NewReader(content))
17		for scanner.Scan() {
18			line := bytes.TrimSpace(scanner.Bytes())
19			if len(line) == 0 {
20				continue
21			}
22			var probe struct {
23				Type    string           `json:"type"`
24				Message *json.RawMessage `json:"message"`
25			}
26			if json.Unmarshal(line, &probe) != nil {
27				continue
28			}
29			if probe.Type == "message" && probe.Message != nil {
30				return true
31			}
32			// If we hit a known Claude Code/Cursor type, it's not Droid.
33			if userAliases[probe.Type] || probe.Type == transcript.TypeAssistant || droppedTypes[probe.Type] {
34				return false
35			}
36		}
37		return false
38	}
39	
40	// compactDroid converts Factory AI Droid JSONL transcripts into the compact
41	// format. Droid uses the same Anthropic Messages API structure as Claude Code
42	// and Cursor, but wraps each message in an envelope that must be unwrapped first.
43	func compactDroid(content []byte, opts MetadataFields) ([]byte, error) {
44		return compactJSONLWith(content, opts, unwrapDroidEnvelope)
45	}
46	
47	// unwrapDroidEnvelope handles Factory AI Droid's envelope format where the
48	// actual message is nested:
49	//
50	//	{"type":"message","message":{"role":"user","content":...}}
51	//
52	// It promotes inner fields (role, content) to the top level and carries over
53	// outer fields (timestamp, id) so the shared converters see a flat structure.
54	// Returns raw unchanged if the line is not a Droid envelope.
55	func unwrapDroidEnvelope(raw map[string]json.RawMessage) map[string]json.RawMessage {
56		if unquote(raw["type"]) != "message" {
57			return raw
58		}
59	
60		msgRaw, ok := raw["message"]
61		if !ok {
62			return raw
63		}
64	
65		var inner map[string]json.RawMessage
66		if json.Unmarshal(msgRaw, &inner) != nil {
67			return raw
